package com.personal.jobagent.email;
import com.personal.jobagent.common.UuidV7; import com.personal.jobagent.application.ApplicationStatusService; import com.personal.jobagent.identity.CredentialVault; import com.personal.jobagent.notifications.NotificationService; import com.personal.jobagent.notifications.NotificationEvents; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.regex.*; import java.sql.Timestamp;
@Service public class EmailIntelligenceService {public record IngestResult(UUID emailId,String classification,UUID applicationId,boolean replayed){} private static final Pattern OTP=Pattern.compile("\\b\\d{4,8}\\b"); private final JdbcTemplate db;private final CredentialVault vault;private final NotificationService notifications;private final ApplicationStatusService statusService;public EmailIntelligenceService(JdbcTemplate d,CredentialVault v,NotificationService n,ApplicationStatusService s){db=d;vault=v;notifications=n;statusService=s;} public IngestResult ingest(String messageId,String from,String to,String subject,String body,Instant received){if(messageId!=null){List<UUID> ids=db.query("select id from emails where message_id=?",(rs,n)->(UUID)rs.getObject(1),messageId);if(!ids.isEmpty()){Map<String,Object> r=db.queryForMap("select id,classification,application_id from emails where id=?",ids.get(0));return new IngestResult((UUID)r.get("id"),(String)r.get("classification"),(UUID)r.get("application_id"),true);}}UUID app=findApplication(subject+" "+body);String c=classify(subject+" "+body);UUID id=UuidV7.generate();db.update("insert into emails(id,message_id,from_address,to_address,subject,body_text,received_at,application_id,classification,classification_confidence,classification_reason) values(?,?,?,?,?,?,?,?,?,?,?)",id,messageId,from,to,subject,body,Timestamp.from(received),app,c,0.95,"deterministic local classifier"); if(app!=null){String event=switch(c){case "INTERVIEW_INVITE"->NotificationEvents.INTERVIEW_INVITATION;case "ASSESSMENT_INVITE"->NotificationEvents.ASSESSMENT_RECEIVED;case "REJECTION"->NotificationEvents.REJECTION_RECEIVED;case "OFFER"->NotificationEvents.OFFER_RECEIVED;case "CONFIRMATION"->NotificationEvents.CONFIRMATION_EMAIL_RECEIVED;default->NotificationEvents.RECRUITER_REPLY;}; notifications.emit(new NotificationService.NotificationCommand(event,"APPLICATION",app,Map.of("email_id",id.toString(),"classification",c),UuidV7.generate(),null));} if(app!=null){String target=switch(c){case "CONFIRMATION"->"CONFIRMATION_RECEIVED";case "INTERVIEW_INVITE"->"INTERVIEW";case "ASSESSMENT_INVITE"->"ASSESSMENT";case "REJECTION"->"REJECTED";case "OFFER"->"OFFER";case "RECRUITER_OUTREACH"->"RECRUITER_CONTACT";default->null;};if(target!=null)try{statusService.apply(app,target,"email:"+id,"EMAIL_INTELLIGENCE",Map.of("email_id",id.toString(),"classification",c));}catch(IllegalStateException ignored){}} return new IngestResult(id,c,app,false);} public Optional<Map<String,Object>> extractVerification(UUID emailId,UUID sessionId,String expectedDomain){Map<String,Object> e=db.queryForMap("select from_address,subject,body_text,received_at from emails where id=?",emailId);String sender=String.valueOf(e.get("from_address")).toLowerCase(Locale.ROOT);if(expectedDomain!=null&&!sender.endsWith("@"+expectedDomain.toLowerCase(Locale.ROOT)))return Optional.empty();Instant received=((java.sql.Timestamp)e.get("received_at")).toInstant();if(received.isBefore(Instant.now().minus(Duration.ofMinutes(30))))return Optional.empty();Matcher m=OTP.matcher(e.get("subject")+" "+e.get("body_text"));if(!m.find())return Optional.empty();String ref=vault.store(m.group(),Duration.ofMinutes(10));UUID id=UuidV7.generate();try{db.update("insert into verification_extractions(id,source_email_id,account_session_id,verification_type,value_ref,confidence,expires_at) values(?,?,?,?,?,?,?)",id,emailId,sessionId,"OTP",ref,0.95,Timestamp.from(Instant.now().plus(Duration.ofMinutes(10))));}catch(org.springframework.dao.DuplicateKeyException ignored){}return Optional.of(Map.of("extractionId",id,"verificationType","OTP","valueAvailable",true));} public String resolve(UUID id){Map<String,Object> r=db.queryForMap("select value_ref,consumed_at,expires_at from verification_extractions where id=?",id);if(r.get("consumed_at")!=null||((Timestamp)r.get("expires_at")).toInstant().isBefore(Instant.now()))throw new IllegalStateException("verification unavailable");if(db.update("update verification_extractions set consumed_at=now() where id=? and consumed_at is null",id)!=1)throw new IllegalStateException("verification already consumed");return vault.resolveOnce((String)r.get("value_ref"));} private UUID findApplication(String t){List<Map<String,Object>> r=db.queryForList("select a.id from applications a join jobs j on j.id=a.job_id where lower(?) like lower('%' || a.id::text || '%') or lower(?) like lower('%' || coalesce(j.company_name_raw,'') || '%')",t,t);return r.size()==1?(UUID)r.get(0).get("id"):null;} private String classify(String t){String s=t.toLowerCase(Locale.ROOT);if(s.contains("interview"))return "INTERVIEW_INVITE";if(s.contains("assessment"))return "ASSESSMENT_INVITE";if(s.contains("reject"))return "REJECTION";if(s.contains("offer"))return "OFFER";if(s.contains("confirm"))return "CONFIRMATION";if(s.contains("recruiter")||s.contains("application"))return "RECRUITER_OUTREACH";return "OTHER";} }